import{_ as r,o as i,c as s,a2 as o}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"libp2p Primer for Soma Developers","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/libp2p-primer.md","filePath":"architecture/libp2p-primer.md","lastUpdated":1780254295000}'),a={name:"architecture/libp2p-primer.md"};function t(n,e,l,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="libp2p-primer-for-soma-developers" tabindex="-1">libp2p Primer for Soma Developers <a class="header-anchor" href="#libp2p-primer-for-soma-developers" aria-label="Permalink to &quot;libp2p Primer for Soma Developers&quot;">​</a></h1><p>Soma builds on libp2p for networking. This primer highlights the concepts you will encounter most often in the codebase and logs.</p><h2 id="peer-identity-peer-id" tabindex="-1">Peer Identity (Peer ID) <a class="header-anchor" href="#peer-identity-peer-id" aria-label="Permalink to &quot;Peer Identity (Peer ID)&quot;">​</a></h2><ul><li>Each daemon generates a keypair (Ed25519 by default) on first launch and derives a Peer ID from the public key.<a href="https://docs.libp2p.io/concepts/security/security-considerations/" target="_blank" rel="noreferrer">^security</a></li><li>Peer IDs are the canonical addresses peers use to authenticate each other; you will see them logged or encoded in invite links (<code>Qm...</code> style multihashes).</li><li>The private key stays on disk with the daemon and is used to sign protocol messages or capability grants. Treat it as the source of truth for user identity.</li></ul><h2 id="protocols" tabindex="-1">Protocols <a class="header-anchor" href="#protocols" aria-label="Permalink to &quot;Protocols&quot;">​</a></h2><ul><li>libp2p multiplexes named protocols (strings like <code>/soma/class/1.0.0</code>) over a single secure connection.</li><li>Soma implements custom behaviours for chat, membership onboarding, content sync, etc., alongside built-in protocols such as identify or ping.</li><li>When you add a new network feature, you usually define a new protocol ID, message schema, and handler to run inside the daemon’s <code>NetworkBehaviour</code>.</li></ul><h2 id="publish-subscribe-gossipsub" tabindex="-1">Publish/Subscribe (Gossipsub) <a class="header-anchor" href="#publish-subscribe-gossipsub" aria-label="Permalink to &quot;Publish/Subscribe (Gossipsub)&quot;">​</a></h2><ul><li>Soma uses libp2p Gossipsub for class-wide topics (chat, join events, announcements).<a href="https://docs.libp2p.io/concepts/publish-subscribe/gossipsub/" target="_blank" rel="noreferrer">^pubsub</a></li><li>Peers subscribe to deterministic topic names per class and publish messages that are cryptographically signed so receivers know who sent them.<a href="https://docs.libp2p.io/concepts/security/security-considerations/" target="_blank" rel="noreferrer">^security</a></li><li>Gossipsub is eventually consistent: there is no total ordering, so design application logic accordingly (e.g., include timestamps or sequence numbers where needed).</li></ul><h2 id="relays-and-direct-connections" tabindex="-1">Relays and Direct Connections <a class="header-anchor" href="#relays-and-direct-connections" aria-label="Permalink to &quot;Relays and Direct Connections&quot;">​</a></h2><ul><li>libp2p always prefers direct connections using the addresses peers advertise (TCP, QUIC, WebRTC).</li><li>When direct dialing fails because of NAT, peers reserve a slot on a Circuit Relay and exchange encrypted traffic through it.<a href="https://docs.libp2p.io/concepts/nat/circuit-relay/" target="_blank" rel="noreferrer">^relay</a></li><li>After establishing a relayed session, libp2p attempts DCUtR (hole punching) to upgrade to a direct link automatically, reducing latency when possible.</li></ul><h2 id="peer-discovery-rendezvous-and-mdns" tabindex="-1">Peer Discovery (Rendezvous and mDNS) <a class="header-anchor" href="#peer-discovery-rendezvous-and-mdns" aria-label="Permalink to &quot;Peer Discovery (Rendezvous and mDNS)&quot;">​</a></h2><ul><li>Soma peers connect to a rendezvous server, register under a namespace (e.g., <code>soma-prod</code>), and query for peers to bootstrap connectivity.<a href="https://docs.libp2p.io/concepts/discovery-routing/rendezvous/" target="_blank" rel="noreferrer">^rendezvous</a></li><li>On local networks developers can enable mDNS, letting daemons auto-discover each other without any infrastructure.</li><li>You will see code paths for both discovery mechanisms—pay attention to configuration files or CLI flags when debugging peers that fail to connect.</li></ul><p>For Soma-specific wiring and CLI flags, see <code>docs/src/architecture/peer-connectivity.md</code>.</p>',13)])])}const b=r(a,[["render",t]]);export{h as __pageData,b as default};
